/* Farol v4 — presentation and explicit, human-authored commands only. */
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const L = {prio:'Prioridade',att:'Atenção',obs:'Observar',ok:'Em dia',unknown:'Sem dados suficientes'};
const statuses = {available_in_app:'Disponível no aplicativo',draft:'Rascunho',reviewed:'Revisado',published:'Publicado',active:'Ativa',archived:'Histórica',todo:'A fazer',doing:'Em andamento',done:'Concluída',high:'Alta',normal:'Normal',low:'Baixa'};
const names = {skipped_hard_study_pct:'Questões difíceis puladas no estudo',hard_study_sessions:'Sessões com difíceis puladas',late_study_sessions:'Sessões a partir de 23h',oldest_unanswered_days:'Tempo da mensagem sem resposta mais antiga',recorded_at:'Registrado em',started_at:'Início',starts_at:'Início',ends_at:'Término',kind:'Tipo',max_score:'Nota máxima',recorded_by:'Autor do registro',questions:'Questões',error:'Causa de erro',seconds:'Tempo por questão (s)',answered:'Respondida',access_days:'Dias sem acesso',days_since_access:'Dias sem acesso',attendance:'Presença',attendance_pct:'Presença',schedule_pct:'Cumprimento do cronograma',schedule:'Cumprimento do cronograma',exam_score:'Nota de simulado',essay_score:'Nota de redação',skipped_hard_study:'Questões difíceis puladas no estudo',study_hard_skips:'Questões difíceis puladas no estudo',question_seconds:'Tempo por questão',avg_question_seconds:'Tempo por questão',study_minutes:'Tempo de estudo registrado',study_hours:'Horas de estudo registradas',response_days:'Dias sem resposta',unanswered_messages:'Mensagens sem resposta',task_completion_pct:'Execução de tarefas',tasks_completed:'Tarefas concluídas',tasks_total:'Total de tarefas',consecutive_absences:'Faltas consecutivas',period:'Período',window:'Janela',window_days:'Janela em dias',current:'Valor observado',observed:'Valor observado',baseline:'Referência histórica',reference:'Referência histórica',threshold:'Limiar',weight:'Peso',rule_id:'Regra',signal:'Sinal',metric:'Indicador',unit:'Unidade',source:'Fonte',reason:'Condição identificada',comparison:'Comparação',enabled:'Habilitada',minimum_history:'Histórico mínimo',value:'Valor',title:'Título',context:'Contexto',error_cause:'Causa de erro',subject:'Disciplina',score:'Nota',date:'Data',occurred_at:'Registro',duration_minutes:'Duração (min)',difficulty:'Dificuldade',skipped:'Pulada',correct:'Correta',type:'Tipo',present:'Presente',content:'Conteúdo',reading:'Leitura',carelessness:'Descuido',time:'Tempo',study:'Estudo',mock:'Simulado',exam:'Simulado',hard:'Difícil',easy:'Fácil',medium:'Média'};
const state = {user:null,csrf:null,dashboard:null,detail:null,tab:'facts',search:'',filter:'all',sort:'level',rules:null,version:null,focus:null,drawerRequest:0,pendingWrites:0};
const main = $('#main'), drawer = $('#drawer');
let toastTimer;
function eventId(prefix='event'){return `${prefix}_${crypto.randomUUID()}`;}
function busyNavigation(){if(!state.pendingWrites)return false;flash('Salvamento pendente. Aguarde a confirmação para navegar.',true);return true;}
function date(value, time = false) { if (!value) return 'Não informado'; const d = new Date(String(value).length === 10 ? `${value}T12:00:00-03:00` : value); return Number.isNaN(+d) ? String(value) : new Intl.DateTimeFormat('pt-BR',time?{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}:{dateStyle:'short',timeZone:'America/Sao_Paulo'}).format(d); }
function period(value) { if (typeof value === 'object' && value) return `${date(value.start || value.from)} a ${date(value.end || value.to)}`; return date(value); }
function initial(name) { return String(name || '?').split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join(''); }
function label(key) { return names[key] || statuses[key] || String(key).replace(/_/g,' '); }
function val(value) { if (value == null) return 'Não disponível'; if (typeof value === 'boolean') return value ? 'Sim' : 'Não'; if (typeof value === 'object') return JSON.stringify(value); return typeof value === 'number' ? new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(value) : (names[value] || String(value)); }
function pill(level) { return `<span class="lvl ${esc(level)}">${esc(L[level] || level)}</span>`; }
function empty(text = 'Nenhum registro neste período.') { return `<p class="empty">${esc(text)}</p>`; }
function button(text, action, attrs = '', primary = false) { return `<button type="button" class="${primary?'btn-sm solid':'btn-sm'}" data-action="${action}" ${attrs}>${text}</button>`; }
function flash(message, error = false) { const t=$('#toast'); t.textContent=message;t.classList.toggle('error',error);t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,6500); }
async function api(path, method='GET', data) {
  let response;
  try { response=await fetch(path,{method,credentials:'same-origin',headers:{Accept:'application/json',...(data===undefined?{}:{'Content-Type':'application/json'}),...(method==='GET'?{}:{'X-CSRF-Token':state.csrf || ''})},body:data===undefined?undefined:JSON.stringify(data)}); }
  catch { throw new Error('Sem conexão com o servidor. Seus campos continuam nesta tela; tente salvar novamente.'); }
  let result;try { result=await response.json(); } catch { throw new Error('O servidor não retornou uma resposta válida. Tente novamente.'); }
  if(!response.ok){if(response.status===401 && path!='/api/login')showLogin();throw new Error(response.status===403?'Sem autorização para este conteúdo.':((result.error || `Falha na solicitação (${response.status}).`) + (Array.isArray(result.details)?' '+result.details.join(' '):'')));}
  return result;
}
function showLogin() { state.user=null;state.csrf=null;$('#app').hidden=true;$('#boot').hidden=true;$('#login').hidden=false;closeDrawer(true);main.replaceChildren();drawer.replaceChildren();state.dashboard=null;state.rules=null;state.version=null;state.search='';state.filter='all';$('#email').focus(); }
function shell(session) { state.user=session.user;state.csrf=session.csrf_token;$('#boot').hidden=true;$('#login').hidden=true;$('#app').hidden=false;$('#meName').textContent=state.user.name;$('#meAv').textContent=initial(state.user.name);$('#roleLabel').textContent={mentor:'Mentor',admin:'Administrador',student:'Aluno'}[state.user.role] || state.user.role; }
async function loadPage() {
  main.setAttribute('aria-busy','true');
  if(!main.hasChildNodes())main.innerHTML='<p role="status">Carregando seus dados…</p>';
  try { if(state.user.role==='mentor'){state.dashboard=await api('/api/dashboard');renderMentor();} else if(state.user.role==='admin'){state.rules=await api('/api/rules');renderAdmin();} else {renderStudent(await api('/api/student/home'));} }
  finally {main.removeAttribute('aria-busy');}
}
async function start() { try { shell(await api('/api/session')); await loadPage(); } catch(error) {if(state.user)pageError(error); else showLogin();} }
function pageError(error) { main.innerHTML=`<div class="page-error" role="alert"><h1>Não foi possível carregar</h1><p>${esc(error.message)}</p>${button('Tentar novamente','reload')}</div>`; }
function metricEntries(metrics) {return Object.entries(metrics||{}).filter(([k,v])=>!k.endsWith('_id') && k!=='period' && v!==undefined);}
function metricValue(v) {return v && typeof v==='object' ? (v.current ?? v.value ?? v.observed) : v;}
function metricsCards(metrics) {return metricEntries(metrics).map(([key,m])=>{const history=(state.detail?.history||[]).filter(h=>h.period!==state.detail?.period).slice(-4).map(h=>metricValue(h.metrics?.[key])).filter(v=>typeof v==='number');const baseline=m?.baseline??(history.length>=2?history.reduce((a,b)=>a+b,0)/history.length:null);return `<div class="metric"><span>${esc(label(key))}</span><b>${esc(val(metricValue(m)))} ${esc(m?.unit || unitFor(key))}</b><small>${baseline!=null?`Referência própria: ${esc(val(baseline))} ${esc(unitFor(key))} · média das ${history.length} semanas anteriores com dados.`:'Histórico insuficiente para comparação.'}</small><small>${esc(m?.source || state.detail?.source || 'Fonte não informada')}</small></div>`;}).join('') || empty('Indicadores ainda indisponíveis.');}
function unitFor(key) {if(key.includes('pct'))return '%';if(key.includes('seconds'))return 's';if(key.includes('minutes'))return 'min';if(key.includes('hours'))return 'h';if(key.includes('days'))return 'dias';if(key.includes('score'))return 'pontos';if(key.includes('sessions'))return 'sessões';return '';}
function evidenceList(alert) {const e=alert.evidence || [];return Array.isArray(e)?e:(e.signals||Object.entries(e).map(([key,value])=>({signal:key,observed:value})));}
function evidenceTitle(e) {return e.title || e.label || label(e.signal || e.rule_id || e.metric || 'Sinal registrado');}
function renderMentor(){
  const d=state.dashboard,s=d.summary||{};
  $('#week').textContent=`Semana de ${period(d.period)}`;
  main.innerHTML=`<div class="greet"><div><p class="eyebrow">SEU PONTO DE ACOMPANHAMENTO</p><h1>Uma semana, cada trajetória.</h1><p class="lead">Os sinais estão aqui. A interpretação e as decisões são suas.</p></div><div class="status-line">${d.students?.length||0} alunos vinculados<br>Atualizado em ${esc(date(d.updated_at,true))} (São Paulo)</div></div>
    <div class="statusbar" role="group" aria-label="Filtrar alunos por nível">${Object.entries(L).map(([k,v])=>`<button class="sb ${k==='prio'?'warn':''}" type="button" data-action="filter" data-level="${k}" aria-pressed="${state.filter===k}"><i class="${{prio:'d-p',att:'d-a',obs:'d-o',ok:'d-k',unknown:'d-o'}[k]}"></i><b>${esc(s[k]??0)}</b>${v}</button>`).join('')}${button('Todos','filter','data-level="all"')}</div>
    <div class="statistics"><div class="stat"><strong>${esc(s.new_alerts??0)}</strong><span>Alertas novos na semana</span></div><div class="stat"><strong>${esc(s.followed??0)}</strong><span>Casos em acompanhamento</span></div><div class="stat"><strong>${esc(s.interventions??0)}</strong><span>Intervenções registradas</span></div><div class="stat"><strong>${esc(d.period?period(d.period):'—')}</strong><span>Período em consulta</span></div></div>
    <div class="tools"><div class="field"><label for="studentSearch">Buscar na sua carteira</label><input type="search" id="studentSearch" placeholder="Nome ou curso" value="${esc(state.search)}"></div><div class="field"><label for="levelFilter">Nível</label><select id="levelFilter"><option value="all">Todos os níveis</option>${Object.entries(L).map(([k,v])=>`<option value="${k}" ${state.filter===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="studentSort">Ordenação</label><select id="studentSort"><option value="level" ${state.sort==='level'?'selected':''}>Nível de atenção</option><option value="name" ${state.sort==='name'?'selected':''}>Nome</option><option value="sync" ${state.sort==='sync'?'selected':''}>Última atualização</option></select></div>${button('Processar sinais','evaluate')}${button('Consultar regras','rules')}</div>
    <div class="board"><section class="sea"><svg class="house" viewBox="0 0 80 200" aria-hidden="true"><use href="#house"/></svg><div class="sweep" aria-hidden="true"></div><div class="sea-head"><h2>Sua turma</h2><span class="mono" id="studentCount"></span></div><div class="grid" id="studentGrid"></div></section><section class="alerts"><div class="alerts-head"><h2>Fila de acompanhamento</h2><span class="mono">Atenção e Prioridade</span></div><div class="queue-list">${(d.queue||[]).map(a=>`<article class="card ${esc(a.level)}"><div class="card-top"><span class="avatar">${esc(initial(a.student_name))}</span><div class="person"><button type="button" data-action="student" data-id="${esc(a.student_id)}" data-tab="alerts">${esc(a.student_name)}</button><small>Detectado ${esc(date(a.detected_at,true))}</small></div>${pill(a.level)}</div><p class="evidence-line">${esc(evidenceList(a).map(evidenceTitle).join(' · ') || 'Consultar dados e regras aplicadas.')}</p><div class="card-actions">${button('Ver evidências e registrar triagem','student',`data-id="${esc(a.student_id)}" data-tab="alerts"`)}</div></article>`).join('') || empty('Nenhum alerta de Atenção ou Prioridade nesta semana.')}</div></section></div>
    <div class="split"><section class="panelbox"><div class="section-head"><h2>Observar · resumo semanal</h2><span class="label">${d.observe?.length||0} alunos</span></div><p class="hint">Sinais isolados ficam neste resumo para sua consulta.</p><div class="compact-list">${(d.observe||[]).map(s=>`<div class="compact-row"><span class="avatar">${esc(initial(s.name || s.student_name))}</span><div class="grow"><p>${esc(s.name || s.student_name)}</p><small>${esc(s.course || 'Sinal isolado no período')}</small></div>${button('Abrir','student',`data-id="${esc(s.id || s.student_id)}" data-tab="alerts"`)}</div>`).join('')||empty('Nenhum aluno no nível Observar.')}</div></section><section class="panelbox"><h2>Variações depois de intervenções</h2><p class="hint">Comparação factual. A avaliação da intervenção pertence ao mentor.</p>${(d.evolution||[]).length?`<div class="table-scroll"><table class="ctable"><thead><tr><th>Aluno / indicador</th><th>Antes</th><th>Depois</th></tr></thead><tbody>${d.evolution.map(e=>`<tr><td>${esc(e.student_name)}<br><small>${esc(label(e.metric))} · ação ${esc(date(e.intervention_at))}</small></td><td>${esc(val(e.before))} ${esc(e.unit||'')}</td><td>${esc(val(e.after))} ${esc(e.unit||'')}</td></tr>`).join('')}</tbody></table></div>`:empty('Ainda não há dados posteriores a uma intervenção para comparar.')}</section></div>
    <div class="split"><section class="panelbox"><h2>Central de notificações</h2><p class="hint">Avisos disponíveis neste aplicativo, com data de registro.</p>${notifications(d.notifications)}</section><section class="panelbox"><h2>Qualidade dos alertas</h2>${quality(d.quality||{})}</section></div>`;
  renderStudents();
}
function renderStudents(){const rank={prio:0,att:1,obs:2,unknown:3,ok:4};const students=(state.dashboard.students||[]).filter(s=>(state.filter==='all'||s.level===state.filter)&&`${s.name} ${s.course}`.toLocaleLowerCase('pt-BR').includes(state.search.toLocaleLowerCase('pt-BR'))).sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name,'pt-BR'):state.sort==='sync'?String(b.last_sync||'').localeCompare(String(a.last_sync||'')):(rank[a.level]-rank[b.level]||a.name.localeCompare(b.name,'pt-BR')));$('#studentCount').textContent=`${students.length} visíveis`;$('#studentGrid').innerHTML=students.map(s=>`<button type="button" class="tile seen ${['prio','att'].includes(s.level)?'lit':''} ${esc(s.level)}" data-action="student" data-id="${esc(s.id)}" title="${esc(s.name)} · ${esc(L[s.level])} · Atualização: ${esc(date(s.last_sync,true))}"><span class="avatar">${esc(initial(s.name))}</span><span class="nm">${esc(s.name)}</span><span class="tile-status">${esc(L[s.level]||'Sem avaliação')}</span><span class="tile-status sync">${s.last_sync?'Sincronizado '+esc(date(s.last_sync)):'Sem sincronização'}</span></button>`).join('')||empty('Nenhum aluno corresponde à busca.');}
function notifications(items){return `<div class="compact-list">${(items||[]).map(n=>`<div class="compact-row notification ${n.read_at?'':'unread'}"><div class="grow"><p>${esc(n.title || n.body || n.message || 'Novo alerta disponível')}</p><small>${esc(date(n.created_at,true))} · in-app</small></div>${!n.read_at?button('Marcar como lida','read',`data-id="${esc(n.id)}"`):'<span class="label">Lida</span>'}</div>`).join('')||empty('Nenhuma notificação.')}</div>`;}
function quality(q){return `<div class="quality-grid">${[['Úteis',q.useful??0],['Não úteis',q.not_useful??0],['Falsos alarmes',q.false_alarms],['Eventos não detectados',q.missed_events],['Antecedência média (dias)',q.lead_days],['Eventos rotulados',q.labelled_count??0]].map(([n,v])=>`<div class="stat"><strong>${v==null?'—':esc(val(v))}</strong><span>${n}</span></div>`).join('')}</div><p class="hint">${esc(q.definition || 'Sem dados rotulados suficientes para medir falsos alarmes, eventos não detectados e antecedência. Utilidade é a avaliação manual do mentor.')}</p>${!q.labelled_count?'<p class="hint">Sem dados suficientes: não há eventos rotulados nesta carteira para medir falsos alarmes, afastamentos não detectados ou antecedência.</p>':''}<p class="hint">Avaliações de utilidade não alteram pesos automaticamente.</p>`;}
function openDrawer(content){if(drawer.hidden)state.focus=document.activeElement;drawer.innerHTML=content;drawer.hidden=false;$('#scrim').hidden=false;$('#app').inert=true;document.body.style.overflow='hidden';drawer.scrollTop=0;($('.x',drawer)||drawer).focus();}
function closeDrawer(force=false){if(!force&&busyNavigation())return;state.drawerRequest++;drawer.removeAttribute('aria-busy');drawer.hidden=true;$('#scrim').hidden=true;$('#app').inert=false;document.body.style.overflow='';state.detail=null;editingDocument=null;if(state.focus?.isConnected&&!$('#app').hidden)state.focus.focus();}
function drawerHead(title,sub=''){return `<div class="drawer-head"><span class="avatar">${esc(initial(title))}</span><div><h2 id="drawerTitle">${esc(title)}</h2><small>${esc(sub)}</small></div><button class="x" type="button" data-action="close" aria-label="Fechar painel">×</button></div>`;}
async function openStudent(id,tab='facts'){
  const request=++state.drawerRequest;
  state.tab=Object.hasOwn(tabs,tab)?tab:'facts';state.detail=null;editingDocument=null;
  openDrawer(drawerHead('Carregando aluno…')+'<p role="status">Consultando dados persistidos…</p>');
  drawer.setAttribute('aria-busy','true');
  try{
    const detail=await api(`/api/students/${encodeURIComponent(id)}`);
    if(request!==state.drawerRequest||drawer.hidden||!state.user)return;
    state.detail=detail;renderDetail();
  }catch(error){
    if(request!==state.drawerRequest||drawer.hidden)return;
    openDrawer(drawerHead('Não foi possível abrir')+`<p class="page-error" role="alert">${esc(error.message)}</p>${button('Tentar novamente','student',`data-id="${esc(id)}" data-tab="${esc(tab)}"`)}`);
  }finally{if(request===state.drawerRequest)drawer.removeAttribute('aria-busy');}
}
const tabs={facts:'Panorama',alerts:'Alertas',work:'Planos e agenda',notes:'Registros privados',reports:'Relatórios',messages:'Mensagens'};
function renderDetail(){const d=state.detail,s=d.student;openDrawer(drawerHead(s.name,`${s.course || 'Curso não informado'} · ${s.age??'Idade não informada'}${s.age?' anos':''} · horários de São Paulo`)+`<div class="tabs" role="tablist" aria-label="Ficha do aluno">${Object.entries(tabs).map(([key,title])=>`<button type="button" role="tab" data-action="tab" data-tab="${key}" id="tab-${key}" aria-controls="detailPane" aria-selected="${state.tab===key}" tabindex="${state.tab===key?0:-1}">${title}</button>`).join('')}</div><div class="pane" id="detailPane" tabindex="0" role="tabpanel" aria-labelledby="tab-${state.tab}">${detailPane()}</div>`);}
function detailPane(){return {facts:renderFacts,alerts:renderAlerts,work:renderWork,notes:renderNotes,reports:renderReports,messages:renderMessages}[state.tab]();}
function keyValues(data){return `<dl class="meta">${Object.entries(data||{}).map(([key,v])=>`<dt>${esc(label(key))}</dt><dd>${esc(val(v))}</dd>`).join('')}</dl>`;}
function rawDetails(title,data){return `<details><summary>${esc(title)}</summary><pre>${esc(JSON.stringify(data,null,2))}</pre></details>`;}
function renderFacts(){const d=state.detail,s=d.student;return `<div class="section-head">${pill(d.evaluation?.level||'unknown')}<span class="hint">${d.sync_status==='synced'?'Sincronizado':'Sem sincronização'} · Última atualização: ${esc(date(s.last_sync,true))} (São Paulo)</span></div><section class="box"><h3>Contexto informado pelo aluno</h3>${keyValues({'Curso desejado':s.course,'Disponibilidade':s.availability,'Restrições':s.restrictions,'Plantões':s.shifts})}</section><section><h3>Indicadores do período</h3><p class="hint">Semana de ${esc(period(d.period))} · comparação com o próprio histórico</p>${d.evaluation?.missing?.length?`<details><summary>Evidências insuficientes para ${d.evaluation.missing.length} condição(ões)</summary><ul>${d.evaluation.missing.map(m=>`<li>${esc(m)}</li>`).join('')}</ul></details>`:''}<div class="metric-grid">${metricsCards(d.metrics)}</div></section>${historyTable(d.history)}<section class="box"><h3>Presença registrada</h3>${factRecords(d.attendance)}</section><section class="box"><h3>Simulados e redações</h3>${factRecords(d.academic)}</section><section class="box"><h3>Estudo e questões</h3><p class="hint">Causas de erro registradas: conteúdo, leitura, descuido ou tempo. Questões de estudo e simulado mantêm contextos distintos.</p>${factRecords(d.study)}</section><section class="box"><h3>Fontes oficiais de referência</h3><p class="hint">TRI / Inep: dados indisponíveis.</p><p class="hint">Pesos SISU por curso: dados indisponíveis.</p></section>`;}
function historyTable(history){if(!history?.length)return empty('Sem histórico semanal suficiente.');const keys=[...new Set(history.flatMap(h=>Object.keys(h.metrics||{})))].slice(0,6);return `<section class="box"><h3>Histórico semanal</h3>${miniHistory(history)}<p class="chart-caption">Fonte: ${esc(state.detail?.source || 'não informada')}. Cada coluna mantém sua unidade.</p><div class="table-scroll"><table class="ctable"><thead><tr><th>Semana</th>${keys.map(k=>`<th>${esc(label(k))} ${unitFor(k)?`(${esc(unitFor(k))})`:''}</th>`).join('')}</tr></thead><tbody>${history.map(h=>`<tr><td>${esc(period(h.period))}</td>${keys.map(k=>`<td>${esc(val(metricValue(h.metrics?.[k])))}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function factRecords(items){if(!items?.length)return empty('Sem registros disponíveis.');return items.map(item=>`<article class="document">${keyValues(Object.fromEntries(Object.entries(item).filter(([k])=>!['id','student_id','created_by','updated_by','payload','questions','recorded_by','author_id'].includes(k)).map(([k,v])=>[k,['occurred_at','started_at','starts_at','ends_at','recorded_at'].includes(k)?date(v,true):k==='present'?Boolean(v):v])))}${Array.isArray(item.questions)?questionsTable(item.questions):''}${item.payload?keyValues(item.payload):''}</article>`).join('');}
function questionsTable(questions){if(!questions.length)return empty('Nenhuma questão registrada nesta sessão.');return `<div class="table-scroll"><table class="ctable"><thead><tr><th>Questão</th><th>Dificuldade</th><th>Registro</th><th>Tempo (s)</th><th>Causa do erro informada</th></tr></thead><tbody>${questions.map((q,i)=>`<tr><td>${esc(q.subject||i+1)}</td><td>${esc(label(q.difficulty||'Não informada'))}</td><td>${q.skipped?'Pulada':q.correct===true||q.correct===1?'Correta':q.correct===false||q.correct===0?'Incorreta':'Não informado'}</td><td>${esc(val(q.seconds??q.time_seconds))}</td><td>${esc(label(q.error_cause||'Não informada'))}</td></tr>`).join('')}</tbody></table></div>`;}
function miniHistory(history){const rows=(history||[]).filter(h=>typeof h.metrics?.schedule_pct==='number');if(!rows.length)return '';return `<div><h4>Cumprimento do cronograma (%)</h4><div class="mini-history" role="img" aria-label="Histórico de cumprimento do cronograma: ${esc(rows.map(r=>`${date(r.period)}: ${r.metrics.schedule_pct}%`).join('; '))}">${rows.map(r=>`<div class="history-column"><b>${esc(r.metrics.schedule_pct)}%</b><i style="height:${Math.max(2,Math.min(100,Number(r.metrics.schedule_pct)))}px"></i><span>${esc(date(r.period))}</span></div>`).join('')}</div></div>`;}

function evidenceHtml(a){
  return `<div class="evidence">${evidenceList(a).map(e=>`<div class="why-row"><strong>${esc(evidenceTitle(e))}</strong><p>${esc(e.reason||'')}</p>${keyValues({'Observado':`${val(e.observed)} ${e.unit||''}`,'Referência própria':e.baseline==null?'Não aplicável ou sem referência histórica':`${val(e.baseline)} ${e.unit||''}`,'Regra':e.rule_id,'Peso / limiar':`${val(e.weight)} / ${val(e.threshold)}${['drop_pct','increase_pct'].includes(e.condition)?'% de variação relativa':''}`,'Janela':`${e.window?.weeks||'—'} semanas; período ${period(e.window?.current_period||a.period)}`,'Agregada na classificação':e.applied!==false})}${e.window?.persistent_periods?.length?`<p class="hint">Variação persistente em ${e.window.persistent_periods.length} semanas consecutivas.</p>`:''}${rawDetails('Rastreabilidade do sinal e parâmetros completos',e)}</div>`).join('')||empty('Sem sinais suficientes nesta avaliação.')}</div>`;
}
function renderAlerts(){return (state.detail.alerts||[]).map(a=>{const t=a.triage||{};return `<section class="box"><div class="section-head"><h3>${esc(period(a.period))}</h3>${pill(a.level)}</div><p class="hint">Detecção: ${esc(date(a.detected_at,true))} · versão ${esc(a.version_id)}</p>${evidenceHtml(a)}${rawDetails('Regra e configuração imutável na época do alerta',a.config_snapshot || a.rule_snapshot || {})}${a.raw_inputs?rawDetails('Dados brutos preservados na avaliação',a.raw_inputs):''}<form class="form" data-form="triage" data-id="${esc(a.id)}"><div class="field"><label for="interpret-${esc(a.id)}">Sua interpretação deste alerta</label><textarea id="interpret-${esc(a.id)}" name="interpretation" maxlength="10000">${esc(t.interpretation||'')}</textarea></div><div class="row"><div class="field"><label for="useful-${esc(a.id)}">O alerta foi útil?</label><select id="useful-${esc(a.id)}" name="useful"><option value="">Ainda não avaliado</option><option value="true" ${t.useful===true||t.useful===1?'selected':''}>Útil</option><option value="false" ${t.useful===false||t.useful===0?'selected':''}>Não útil</option></select></div></div><label class="check"><input type="checkbox" name="following" ${t.following?'checked':''}> Em acompanhamento</label><label class="check"><input type="checkbox" name="acted" ${t.acted?'checked':''}> Decidi agir sobre este alerta</label><button class="btn-sm solid" type="submit">Salvar triagem</button><p class="form-status" role="status"></p></form>${t.created_at?`<p class="authorship">Último registro: ${esc(t.author_name||'mentor')} · ${esc(date(t.created_at,true))}</p>`:''}${a.triage_history?.length?rawDetails('Histórico de decisões do mentor',a.triage_history):''}</section>`;}).join('')||empty('Nenhum alerta registrado. A ausência de evidências não equivale a Em dia.');}
function author(item){return `${esc(item.author_name||item.actor_name||'Autoria registrada')} · ${esc(date(item.updated_at||item.created_at,true))}${item.revision?` · revisão ${esc(item.revision)}`:''}`;}
function documentHtml(item,kind,editable=true){return `<article class="document"><div class="section-head"><h4>${esc(item.title||'Registro')}</h4>${item.status?`<span class="label">${esc(statuses[item.status]||item.status)}</span>`:''}</div><p class="prose">${esc(item.body)}</p><p class="authorship">${author(item)}</p>${item.period?`<p class="hint">Período: ${esc(period(item.period))}</p>`:''}${item.activities?.length?`<ul>${item.activities.map(a=>`<li>${esc(a.title)} · prioridade ${esc(statuses[a.priority]||a.priority)} · ${esc(date(a.due_at))}</li>`).join('')}</ul>`:''}${item.reviewed_at?`<p class="hint">Revisado por ${esc(item.reviewer_name||(item.reviewer_id===state.user?.id?state.user.name:item.reviewer_id)||'mentor')} em ${esc(date(item.reviewed_at,true))}</p>`:''}${item.published_revision&&item.status!=='published'?`<p class="privacy">A revisão ${esc(item.published_revision)} continua publicada; esta revisão ${esc(item.revision)} está privada.</p>`:''}${kind==='report'?`<p class="hint">${item.audience==='student_and_authorized_guardians'?'Acesso: aluno e responsáveis autorizados.':'Acesso: somente o aluno.'} Disponível autenticado quando publicado · não enviado externamente.</p>`:''}${editable&&kind?button('Editar / consultar revisões','edit-document',`data-kind="${kind}" data-id="${esc(item.id)}"`):''}${item.history?.length?rawDetails('Histórico de revisões',item.history):''}</article>`;}
function simpleForm(kind,labelText,buttonText){return `<form class="form" data-form="${kind}"><div class="field"><label for="${kind}-body">${labelText}</label><textarea id="${kind}-body" name="body" required maxlength="10000"></textarea></div><button class="btn-sm solid" type="submit">${buttonText}</button><p class="form-status" role="status"></p></form>`;}
function renderNotes(){const d=state.detail;return `<section class="box"><h3>Anotação privada</h3><p class="privacy">Visível somente ao mentor autor. Registre apenas o contexto necessário ao acompanhamento; evite informações sensíveis desnecessárias.</p>${simpleForm('note','Escreva sua anotação','Salvar anotação privada')}</section><section class="box"><h3>Histórico de anotações</h3>${(d.notes||[]).map(n=>documentHtml(n)+button('Editar anotação','edit-note',`data-id="${esc(n.id)}"`)).join('')||empty('Você ainda não registrou anotações.')}</section><section class="box"><h3>Registrar intervenção</h3><p class="hint">Descreva uma ação decidida por você. O registro não representa uma avaliação automática do resultado.</p><form class="form" data-form="intervention"><div class="field"><label for="intervention-body">O que você fez ou decidiu</label><textarea id="intervention-body" name="body" required maxlength="10000"></textarea></div><div class="field"><label for="intervention-alert">Relacionar a um alerta (opcional)</label><select id="intervention-alert" name="alert_id"><option value="">Sem vínculo com alerta</option>${(d.alerts||[]).map(a=>`<option value="${esc(a.id)}">${esc(period(a.period))} · ${esc(L[a.level])}</option>`).join('')}</select></div><button class="btn-sm solid" type="submit">Registrar intervenção</button><p class="form-status" role="status"></p></form></section><section class="box"><h3>Intervenções registradas</h3>${(d.interventions||[]).map(n=>documentHtml(n)).join('')||empty('Nenhuma intervenção registrada.')}</section>`;}
function renderMessages(){return `<section class="box"><h3>Mensagem para o aluno</h3><p class="privacy">Compartilhada com o aluno no aplicativo. Autoria: ${esc(state.user.name)}. Não há envio externo configurado.</p>${simpleForm('message','Escreva sua mensagem','Disponibilizar mensagem')}</section><section class="box"><h3>Histórico de mensagens</h3>${(state.detail.messages||[]).map(m=>`${documentHtml(m)}<p class="hint">${m.read_at?`Leitura registrada: ${esc(date(m.read_at,true))}`:'Disponível in-app · leitura não informada'} · não enviado externamente</p>`).join('')||empty('Nenhuma mensagem disponível.')}</section>`;}
function renderTasks(tasks,student=false){return (tasks||[]).length?`<div class="table-scroll"><table class="ctable"><thead><tr><th>Atividade</th><th>Prazo</th><th>Execução</th></tr></thead><tbody>${tasks.map(t=>`<tr><td>${esc(t.title)}${t.priority?`<br><small>Prioridade ${esc(statuses[t.priority]||t.priority)}</small>`:''}${t.updated_by_name?`<br><small>Atualizada por ${esc(t.updated_by_name)}</small>`:''}</td><td>${esc(date(t.due_at))}${t.overdue?'<br><span class="label overdue">Prazo ultrapassado</span>':''}</td><td>${student?`<select aria-label="Estado da tarefa ${esc(t.title)}" class="select task-state" data-task="${esc(t.id)}" data-revision="${esc(t.revision||1)}" data-previous="${esc(t.status)}">${['todo','doing','done'].map(v=>`<option value="${v}" ${t.status===v?'selected':''}>${statuses[v]}</option>`).join('')}</select>`:`${esc(statuses[t.status]||t.status)}${t.updated_at?`<br><small>${esc(date(t.updated_at,true))}</small>`:''}`}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma tarefa registrada.');}
function renderWork(){return `<section class="box"><div class="section-head"><h3>Planos, metas e orientações</h3>${button('Criar plano','new-document','data-kind="plan"',true)}</div><p class="privacy">Rascunhos permanecem privados. Planos publicados ficam disponíveis ao aluno. Toda atividade e prioridade é definida pelo mentor.</p>${(state.detail.plans||[]).map(p=>documentHtml(p,'plan')).join('')||empty('Nenhum plano escrito ainda.')}</section><section class="box"><h3>Execução das tarefas</h3><p class="hint">Atualizações do aluno sincronizadas pelo serviço de integração.</p>${renderTasks(state.detail.tasks)}</section><section class="box"><h3>Agenda do aluno</h3>${factRecords(state.detail.agenda)}</section>`;}
function renderReports(){return `<section class="box"><div class="section-head"><h3>Relatório semanal individual</h3>${button('Escrever relatório','new-document','data-kind="report"',true)}</div><p class="privacy">O texto é escrito e revisado pelo mentor. Para menores, aluno e responsáveis autorizados consultam o mesmo conteúdo mediante acesso autenticado; adultos compartilham apenas com o próprio aluno.</p><p class="hint">Consulte as evidências na aba Panorama. Rascunho → revisado → publicado. Não enviado externamente.</p>${(state.detail.reports||[]).map(r=>documentHtml(r,'report')).join('')||empty('Nenhum relatório escrito ainda.')}</section>`;}
let editingDocument=null;
function activityRow(a={}) {return `<div class="activity" data-id="${esc(a.id||eventId('activity'))}"><div class="field"><label>Atividade<input name="activity_title" value="${esc(a.title||'')}" required maxlength="180"></label></div><div class="field"><label>Prioridade<select name="activity_priority">${['normal','high','low'].map(v=>`<option value="${v}" ${a.priority===v?'selected':''}>${statuses[v]}</option>`).join('')}</select></label></div><div class="field"><label>Prazo<input name="activity_due" type="date" value="${esc(a.due_at?.slice(0,10)||'')}" required></label></div><button type="button" class="btn-sm remove-activity" data-action="remove-activity" aria-label="Remover atividade">×</button></div>`;}
function editDocument(kind,id){const item=id?(state.detail[kind==='plan'?'plans':'reports']||[]).find(i=>i.id===id):null;editingDocument={kind,item};$('#detailPane').innerHTML=`<section class="box"><div class="section-head"><h3>${item?'Editar':'Escrever'} ${kind==='plan'?'plano / orientação':'relatório'}</h3>${button('Voltar','cancel-document')}</div><p class="privacy">Autoria: ${esc(state.user.name)}. ${item?'A nova revisão preserva o histórico.':'Os campos começam em branco para sua autoria.'}</p><form class="form" data-form="document"><div class="field"><label for="document-title">Título</label><input id="document-title" name="title" value="${esc(item?.title||'')}" maxlength="180" required></div><div class="field"><label for="document-period">Início da semana</label><input id="document-period" name="period" type="date" value="${esc(item?.period||state.detail.period||'')}" required></div><div class="field"><label for="document-body">${kind==='plan'?'Plano, metas e orientações':'Corpo do relatório'} · texto do mentor</label><textarea id="document-body" name="body" required maxlength="10000">${esc(item?.body||'')}</textarea></div>${kind==='plan'?`<h3>Atividades definidas por você</h3><div id="activities" class="form">${(item?.activities||[]).map(activityRow).join('')}</div>${button('Adicionar atividade','add-activity')}`:''}<div class="field"><label for="document-status">Estado</label><select id="document-status" name="status"><option value="draft" ${!item||item.status==='draft'||(kind==='report'&&item.status==='published')?'selected':''}>Rascunho privado</option>${kind==='plan'?`<option value="published" ${item?.status==='published'?'selected':''}>Publicar para o aluno</option>`:item?`<option value="reviewed" ${item.status==='reviewed'?'selected':''}>Revisado por mim</option>${item.status==='reviewed'?'<option value="published">Publicar relatório revisado</option>':''}`:''}</select></div><p class="hint">${kind==='report'?'Salve o rascunho, revise explicitamente e então publique. Alterações no texto exigem nova revisão.':'A publicação disponibiliza o plano pela API do aluno e registra sua autoria.'}</p><button class="btn-sm solid" type="submit">Salvar ${kind==='plan'?'plano':'relatório'}</button><p class="form-status" role="status"></p></form>${item?.history?.length?rawDetails('Revisões anteriores',item.history):''}</section>`;$('#document-title').focus();}
function syncReportState(){
  if(editingDocument?.kind!=='report'||editingDocument.item?.status!=='reviewed')return;
  const item=editingDocument.item, form=$('[data-form="document"]');
  const changed=['title','body','period'].some(key=>$(`[name="${key}"]`,form).value.trim()!==item[key]);
  const select=$('[name="status"]',form), publish=$('option[value="published"]',select);
  if(publish)publish.disabled=changed;
  if(changed&&select.value==='published')select.value='draft';
}

async function showRules(){const data=await api('/api/rules');openDrawer(drawerHead('Regras de classificação','Consulta somente leitura · alterações exclusivas do Administrador')+data.versions.map(v=>`<section class="box"><div class="section-head"><h3>${esc(v.name)}</h3><span class="label">${v.id===data.active_id?'Ativa':esc(statuses[v.status]||v.status)}</span></div><p class="hint">Versão ${esc(v.id)} · criada em ${esc(date(v.created_at,true))}</p>${ruleTable(v.config)}${rawDetails('Configuração completa',v.config)}</section>`).join(''));}
function ruleTable(config){return `<div class="table-scroll"><table class="ctable"><thead><tr><th>Sinal</th><th>Condição / limiar</th><th>Peso</th><th>Janela</th></tr></thead><tbody>${(Array.isArray(config?.rules)?config.rules:[]).map(r=>r&&typeof r==='object'?`<tr><td>${esc(r.label||r.id)}<br><small>${r.enabled?'Habilitada':'Desabilitada'}${r.priority?' · gatilho de Prioridade':''}</small></td><td>${esc(r.condition)} ${esc(val(r.threshold))}${r.condition==='drop_pct'||r.condition==='increase_pct'?'%':''}${r.days_threshold!=null?` / ${esc(r.days_threshold)} dias`:''}</td><td>${esc(r.weight)}</td><td>${esc(r.window_weeks)} semana(s)</td></tr>`:`<tr><td colspan="4">Regra inválida: ${esc(JSON.stringify(r))}</td></tr>`).join('')}</tbody></table></div>`;}
function renderAdmin(){const data=state.rules;const current=data.versions.find(v=>v.id===state.version)||data.versions.find(v=>v.id===data.active_id)||data.versions[0];state.version=current?.id;$('#week').textContent='Configuração de regras';main.innerHTML=`<div class="greet"><div><p class="eyebrow">ADMINISTRAÇÃO · CONFIGURAÇÃO</p><h1>Regras claras, versões preservadas.</h1><p class="lead">Edite rascunhos, compare resultados e ative uma versão com justificativa.</p></div>${button('Auditoria','audit')}${button('Vínculos aluno–mentor','assignments')}</div><p class="privacy">Uma versão ativa por processamento. Rascunhos e simulações não alteram alertas de produção. Ativar ou restaurar afeta somente avaliações futuras.</p><div class="admin-grid"><section class="panelbox"><h2>Versões</h2><div class="version-list">${data.versions.map(v=>`<button type="button" class="version" data-action="version" data-id="${esc(v.id)}" aria-pressed="${v.id===state.version}"><b>${esc(v.name)}</b><small>${v.id===data.active_id?'Ativa':esc(statuses[v.status]||v.status)} · ${esc(date(v.created_at))}</small></button>`).join('')}</div>${button('Criar rascunho a partir desta versão','new-version')}</section><section class="panelbox" id="versionEditor">${current?versionEditor(current):empty('Nenhuma versão disponível.')}</section></div>`;}
function versionEditor(v,newDraft=false){const editable=newDraft||v.status==='draft';return `<div class="section-head"><h2>${newDraft?'Novo rascunho':esc(v.name)}</h2><span class="label">${newDraft?'Rascunho':v.id===state.rules.active_id?'Ativa':esc(statuses[v.status]||v.status)}</span></div><p class="hint">${editable?'Altere sinais, condições, pesos, janelas, limiares e precedência no JSON abaixo. A validação no servidor impede configurações inválidas.':'Esta versão é imutável. Crie um rascunho para editar.'}</p>${ruleTable(v.config)}<form class="form" data-form="version" ${newDraft?'data-new="true"':''}><div class="field"><label for="version-name">Nome da versão</label><input name="name" id="version-name" value="${newDraft?'':esc(v.name)}" required maxlength="120" ${editable?'':'readonly'}></div><div class="field"><label for="version-config">Configuração completa (JSON)</label><textarea class="json-editor" name="config" id="version-config" spellcheck="false" ${editable?'':'readonly'}>${esc(JSON.stringify(v.config,null,2))}</textarea></div><div class="field"><label for="version-reason">Justificativa da alteração, ativação ou restauração</label><textarea id="version-reason" name="reason" required maxlength="1000"></textarea></div>${editable?'<button class="btn-sm solid" type="submit">Salvar rascunho</button>':''}<p class="form-status" role="status"></p></form>${newDraft?'':`<div class="card-actions">${button('Validar versão salva','validate-version')}${button('Simular contra versão ativa','simulate-version')}${v.status==='draft'?button('Ativar versão salva','activate-version','',true):v.id!==state.rules.active_id?button('Restaurar para avaliações futuras','restore-version','',true):''}</div><p class="hint">Validação, simulação e ativação utilizam a versão salva no servidor.</p>`}<div id="ruleResult" aria-live="polite"></div>`;}
async function ruleAction(action){const id=state.version;const saved=state.rules.versions.find(v=>v.id===id);if(saved?.status==='draft'&&($('#version-config').value!==JSON.stringify(saved.config,null,2)||$('#version-name').value!==saved.name))throw new Error('Salve as alterações do rascunho antes de validar, simular ou ativar.');const reason=$('#version-reason')?.value.trim();if(['activate','restore'].includes(action)&&!reason)throw new Error('Escreva a justificativa antes de alterar a versão ativa.');const result=await api(`/api/rules/${encodeURIComponent(id)}/${action}`,'POST',action==='simulate'?{compare_id:state.rules.active_id}:['activate','restore'].includes(action)?{reason}:{});if(['activate','restore'].includes(action)){state.version=result.active_id||result.id;flash('Versão aplicada somente às próximas avaliações.');state.rules=await api('/api/rules');renderAdmin();return;}$('#ruleResult').innerHTML=action==='simulate'?`<section class="box"><h3>Comparação da simulação</h3><p class="hint">Resultados simulados; alertas de produção preservados.</p><div class="table-scroll"><table class="ctable"><thead><tr><th>Aluno</th><th>Versão ativa</th><th>Versão selecionada</th></tr></thead><tbody>${(result.results||[]).map(r=>`<tr><td>${esc(r.student_name||r.student_id)}</td><td>${esc(L[r.before?.level||r.before]||r.before?.level||r.before)}</td><td>${esc(L[r.after?.level||r.after]||r.after?.level||r.after)}</td></tr>`).join('')}</tbody></table></div>${rawDetails('Resultado completo da simulação',result)}</section>`:`<p class="${result.valid?'note-ok':'page-error'}">${result.valid?'Configuração válida para uso.':'Configuração inválida: '+esc((result.errors||[]).join(' '))}</p>${rawDetails('Resultado da validação',result)}`;}
async function showAudit(){const result=await api('/api/audit');const items=Array.isArray(result)?result:result.events||result.audit||[];openDrawer(drawerHead('Trilha de auditoria','Ator, momento, justificativa e alterações registradas')+(items.length?items.map(a=>`<section class="box"><h3>${esc(a.action||a.event||'Alteração')}</h3><p class="authorship">${esc(a.actor_name||a.actor_id||'Sistema')} · ${esc(date(a.occurred_at||a.created_at||a.at,true))}</p>${a.reason?`<p>${esc(a.reason)}</p>`:''}${rawDetails('Metadados do evento',a)}</section>`).join(''):empty('Nenhum evento disponível.')));}
async function showAssignments(){const data=await api('/api/assignments');const links=data.links||[];openDrawer(drawerHead('Vínculos aluno–mentor','Configuração mínima da carteira de acompanhamento')+(data.students||[]).map(s=>{const link=links.find(l=>l.student_id===s.id && l.active!==false);return `<section class="box"><h3>${esc(s.name)}</h3><form class="form" data-form="assignment" data-id="${esc(s.id)}"><div class="field"><label for="mentor-${esc(s.id)}">Mentor responsável</label><select name="mentor_id" id="mentor-${esc(s.id)}" required><option value="">Selecionar mentor</option>${(data.mentors||[]).map(m=>`<option value="${esc(m.id)}" ${m.id===(link?.mentor_id||s.mentor_id)?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="reason-${esc(s.id)}">Justificativa</label><input name="reason" id="reason-${esc(s.id)}" required maxlength="1000"></div><button class="btn-sm" type="submit">Salvar vínculo</button><p class="form-status" role="status"></p></form></section>`;}).join(''));}
function renderStudent(data){$('#week').textContent='Área do aluno';main.innerHTML=`<div class="greet"><div><p class="eyebrow">CONTEÚDO COMPARTILHADO PELO MENTOR</p><h1>${data.reports_only?'Relatórios autorizados':`Olá, ${esc(data.student?.name||state.user.name)}.`}</h1><p class="lead">${data.reports_only?'Consulta autenticada ao conteúdo autorizado para responsáveis.':'Consulte orientações publicadas e registre a execução de suas tarefas.'}</p></div></div>${data.reports_only?'':`<div class="split"><section class="panelbox"><h2>Planos e orientações</h2>${(data.plans||[]).map(p=>documentHtml(p,'plan',false)).join('')||empty('Seu mentor ainda não publicou um plano.')}</section><section class="panelbox"><h2>Minhas tarefas</h2><p class="hint">Cada atualização é atribuída à sua conta e sincronizada com o mentor.</p>${renderTasks(data.tasks,true)}</section></div><div class="split"><section class="panelbox"><h2>Mensagens do mentor</h2>${(data.messages||[]).map(m=>documentHtml(m)).join('')||empty('Nenhuma mensagem disponível.')}</section><section class="panelbox"><h2>Agenda</h2>${factRecords(data.agenda)}</section></div>`}<section class="panelbox"><h2>Relatórios publicados</h2><p class="hint">Disponíveis nesta área autenticada · não enviados externamente.</p>${(data.reports||[]).map(r=>documentHtml(r,'report',false)).join('')||empty('Nenhum relatório publicado.')}</section>`;}
async function reloadDetail(){const id=state.detail?.student.id;if(!id)return;state.detail=await api(`/api/students/${encodeURIComponent(id)}`);editingDocument=null;renderDetail();try{state.dashboard=await api('/api/dashboard');renderMentor();}catch(error){flash('Ficha atualizada. O resumo semanal aguarda nova consulta: '+error.message,true);}}
async function saveForm(form){
  if(busyNavigation()||form.dataset.saved)return;
  const type=form.dataset.form, fd=new FormData(form), body=Object.fromEntries(fd);
  const status=$('.form-status',form), controls=$$('button,input,select,textarea',form).filter(c=>!c.disabled);
  status.textContent='Salvamento pendente…';status.classList.remove('error');
  controls.forEach(c=>c.disabled=true);form.setAttribute('aria-busy','true');state.pendingWrites++;
  let saved=false;
  try{
    const sid=state.detail?.student.id;
    if(type==='triage'){
      await api(`/api/alerts/${encodeURIComponent(form.dataset.id)}/triage`,'POST',{interpretation:body.interpretation,useful:body.useful===''?null:body.useful==='true',following:fd.has('following'),acted:fd.has('acted')});
    }else if(type==='note'){
      await api(`/api/students/${sid}/notes`,'POST',{body:body.body});
    }else if(type==='edit-note'){
      await api(`/api/notes/${form.dataset.id}`,'PUT',{body:body.body,revision:Number(form.dataset.revision)});
    }else if(type==='intervention'){
      await api(`/api/students/${sid}/interventions`,'POST',{body:body.body,...(body.alert_id?{alert_id:body.alert_id}:{})});
    }else if(type==='message'){
      await api(`/api/students/${sid}/messages`,'POST',{body:body.body});
    }else if(type==='document'){
      const {kind,item}=editingDocument;
      const data={title:body.title,body:body.body,period:body.period,status:body.status};
      if(kind==='plan')data.activities=$$('.activity',form).map(row=>({id:row.dataset.id,title:$('[name="activity_title"]',row).value,priority:$('[name="activity_priority"]',row).value,due_at:$('[name="activity_due"]',row).value}));
      if(item)data.revision=item.revision;
      await api(item?`/api/${kind==='plan'?'plans':'reports'}/${item.id}`:`/api/students/${sid}/${kind==='plan'?'plans':'reports'}`,item?'PUT':'POST',data);
    }else if(type==='version'){
      let config;try{config=JSON.parse(body.config);}catch{throw new Error('O JSON da configuração contém um erro de sintaxe. Confira vírgulas, aspas e chaves.');}
      const result=await api(form.dataset.new?'/api/rules':`/api/rules/${state.version}`,form.dataset.new?'POST':'PUT',{name:body.name,config,reason:body.reason});
      saved=true;state.version=result.id||result.version?.id||state.version;state.rules=await api('/api/rules');renderAdmin();
      flash(result.errors?.length?'Rascunho salvo com erros de validação. Corrija antes de ativar.':'Rascunho salvo. A produção permanece com a versão ativa.',Boolean(result.errors?.length));
      if(result.errors?.length)$('#ruleResult').innerHTML=`<p class="page-error">${esc(result.errors.join(' '))}</p>`;
      return;
    }else if(type==='assignment'){
      await api(`/api/assignments/${form.dataset.id}`,'PUT',{mentor_id:body.mentor_id,reason:body.reason});
      status.textContent='Vínculo salvo e auditado.';flash('Vínculo atualizado.');return;
    }
    saved=true;form.dataset.saved='true';
    status.textContent='Registro salvo. Atualizando a consulta…';
    await reloadDetail();
    flash(type==='message'?'Mensagem disponível in-app. Não enviada externamente.':'Registro salvo com autoria e data.');
  }catch(error){
    if(saved){
      form.dataset.saved='true';
      status.textContent='Registro salvo no servidor. A consulta não foi atualizada. Use “Consultar registro salvo” para recarregar sem duplicar o envio.';
      if(form.isConnected)form.insertAdjacentHTML('beforeend',button('Consultar registro salvo',type==='version'?'reload':'refresh-detail'));
      flash('O registro foi salvo, mas a atualização da tela falhou. '+error.message,true);
    }else{status.textContent=error.message;}
    status.classList.add('error');
  }finally{
    state.pendingWrites--;form.removeAttribute('aria-busy');
    if(!saved)controls.forEach(c=>c.disabled=false);
  }
}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,submit=$('button',form);submit.disabled=true;submit.textContent='Autenticando…';$('#loginError').textContent='';try{shell(await api('/api/login','POST',{email:$('#email').value,password:$('#senha').value}));$('#senha').value='';await loadPage();}catch(error){if(state.user)pageError(error);else $('#loginError').textContent=error.message;}finally{submit.disabled=false;submit.textContent='Entrar';}});
$('#logout').addEventListener('click',async()=>{if(busyNavigation())return;try{await api('/api/logout','POST',{});state.csrf=null;showLogin();}catch(e){flash(e.message,true);}});
$('#refresh').addEventListener('click',async e=>{if(busyNavigation())return;e.currentTarget.disabled=true;try{await loadPage();flash('Dados atualizados.');}catch(error){flash(error.message,true);}finally{$('#refresh').disabled=false;}});
$('#scrim').addEventListener('click',()=>closeDrawer());
document.addEventListener('submit',e=>{if(e.target.matches('form[data-form]')){e.preventDefault();saveForm(e.target,e.submitter);}});
document.addEventListener('input',e=>{if(e.target.closest('[data-form="document"]'))syncReportState();if(e.target.id==='studentSearch'){state.search=e.target.value;renderStudents();}});
document.addEventListener('change',async e=>{if(e.target.id==='levelFilter'){state.filter=e.target.value;$$('[data-action="filter"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.level===state.filter)));renderStudents();}if(e.target.id==='studentSort'){state.sort=e.target.value;renderStudents();}if(e.target.matches('[data-task]')){const control=e.target;control.disabled=true;try{await api(`/api/tasks/${control.dataset.task}`,'PATCH',{status:control.value,event_id:crypto.randomUUID(),revision:Number(control.dataset.revision)});await loadPage();flash('Execução sincronizada com o mentor.');}catch(error){control.value=control.dataset.previous;flash(error.message,true);}finally{control.disabled=false;}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;if(busyNavigation())return;try{
 if(action==='close')closeDrawer();
 else if(action==='reload')await loadPage();
 else if(action==='refresh-detail')await reloadDetail();
 else if(action==='filter'){state.filter=b.dataset.level;renderMentor();}
 else if(action==='student')await openStudent(b.dataset.id,b.dataset.tab||'facts');
 else if(action==='tab'){state.tab=b.dataset.tab;editingDocument=null;renderDetail();$(`#tab-${state.tab}`,drawer)?.focus();}
 else if(action==='rules')await showRules();
 else if(action==='evaluate'){b.dataset.originalText=b.textContent;b.disabled=true;b.textContent='Processando…';await api('/api/evaluate','POST',{});await loadPage();flash('Sinais processados. Evidências e notificações atualizadas.');}
 else if(action==='read'){await api(`/api/notifications/${b.dataset.id}/read`,'POST',{});await loadPage();}
 else if(action==='new-document')editDocument(b.dataset.kind);
 else if(action==='edit-document')editDocument(b.dataset.kind,b.dataset.id);
 else if(action==='edit-note'){const n=state.detail.notes.find(n=>n.id===b.dataset.id);$('#detailPane').innerHTML=`<section class="box"><h3>Editar anotação privada</h3><p class="privacy">A revisão anterior permanece no histórico. Visível somente ao mentor autor.</p><form class="form" data-form="edit-note" data-id="${esc(n.id)}" data-revision="${n.revision}"><div class="field"><label for="edit-note-body">Sua anotação</label><textarea id="edit-note-body" name="body" required maxlength="10000">${esc(n.body)}</textarea></div><button class="btn-sm solid" type="submit">Salvar revisão</button><p class="form-status" role="status"></p></form>${button('Voltar','cancel-document')}</section>`;$('#edit-note-body').focus();}
 else if(action==='cancel-document'){editingDocument=null;renderDetail();}
 else if(action==='add-activity'){$('#activities').insertAdjacentHTML('beforeend',activityRow());$('#activities .activity:last-child input').focus();}
 else if(action==='remove-activity')b.closest('.activity').remove();
 else if(action==='version'){state.version=b.dataset.id;renderAdmin();}
 else if(action==='new-version'){$('#versionEditor').innerHTML=versionEditor(state.rules.versions.find(v=>v.id===state.version),true);$('#version-name').focus();}
 else if(action.endsWith('-version')){b.disabled=true;state.pendingWrites++;try{await ruleAction(action.replace('-version',''));}finally{state.pendingWrites--;}}
 else if(action==='audit')await showAudit();
 else if(action==='assignments')await showAssignments();
 }catch(error){flash(error.message,true);}finally{b.disabled=false;if(b.dataset.originalText)b.textContent=b.dataset.originalText;}});
document.addEventListener('keydown',e=>{if(drawer.hidden)return;if(e.key==='Escape'){e.preventDefault();closeDrawer();return;}if(e.target.matches('[role="tab"]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const list=$$('[role="tab"]',drawer);let i=list.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;list[i].click();return;}if(e.key==='Tab'){const focusable=$$('button:not([disabled]):not([tabindex="-1"]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href],summary,[tabindex="0"]',drawer).filter(el=>el.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(!first){e.preventDefault();drawer.focus();}else if(e.shiftKey&&(document.activeElement===first||document.activeElement===drawer||!drawer.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!drawer.contains(document.activeElement))){e.preventDefault();first.focus();}}});
window.addEventListener('beforeunload',e=>{if(state.pendingWrites){e.preventDefault();e.returnValue='';}});
window.addEventListener('offline',()=>flash('Você está offline. Os campos permanecem na tela; salve quando a conexão voltar.',true));
window.addEventListener('online',()=>flash('Conexão restabelecida. Você pode salvar ou atualizar os dados.'));
start();
